from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class ChannelParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        cell_ent = self.enb_ent_config['cells'][self.cell_num]
        radio_id = cell_ent['channels'][int(self.mo_num) - 1]['radio']

        base, antl_id, rmod_id = 0, 0, 0
        for radio_num in sorted(self.enb_ent_config['radios'].keys(), key=int):
            radio_ent = self.enb_ent_config['radios'][radio_num]
            antenna_count = int(radio_ent['antenna_count'])
            if radio_num == radio_id:
                channel_ent = cell_ent['channels'][int(self.mo_num) - 1]
                rmod_id = int(channel_ent['radio'])
                port_id = int(channel_ent['port'])
                antl_id = base + port_id
            base += antenna_count

        self.set_parameter('antlDN', f'MRBTS-{self.enb_ent_config["id"]}/EQM-1/APEQM-1/RMOD-{rmod_id}/ANTL-{antl_id}')
        self.set_parameter('direction', cell_ent['channels'][int(self.mo_num) - 1]['direction'])
